import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import org.lwjgl.glfw.GLFW;
import org.lwjgl.opengl.*;
/** Actual capture replay; original binaries or captured, hash-verified source only. */
public final class R8RealChainGpu extends ModelPopulationGpuValidation {
 static List<String> differences(Map<String,Object> a,Map<String,Object> b){var fields=new ArrayList<String>();for(String key:a.keySet())if(!Objects.equals(a.get(key),b.get(key)))fields.add(key);return fields;}
 static Map<String,String> digests(Map<String,Object> state){var out=new TreeMap<String,String>();state.forEach((k,v)->out.put(k,com.iridium126.createmanaindustry.client.particles.engine.hardware.HardwareBackendRuntime.sha(new Gson().toJson(v))));return out;}
 static void compare(Map<String,Object> expected,Map<String,Object> actual,boolean relaxed){var different=differences(expected,actual);if(relaxed)different.remove("particle_multiset");check(different.isEmpty(),"actual complete chain fields differ: "+different);}
 public static void main(String[] args)throws Exception{
  Path out=Path.of(System.getProperty("cmi.benchmark.output")),input=Path.of(System.getProperty("cmi.r7.capture"));Files.createDirectories(out);check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);R7ChainReplayGpu.contextForCapture(input);long window=GLFW.glfwCreateWindow(32,32,"R8 real full chain",0,0);GLFW.glfwMakeContextCurrent(window);GL.createCapabilities();var captured=JsonParser.parseString(Files.readString(input.resolve("manifest.json"))).getAsJsonObject();var result=new LinkedHashMap<String,Object>();result.put("input_manifest_sha256",HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(input.resolve("manifest.json")))));result.put("actual_context_flags",GL11.glGetInteger(GL30.GL_CONTEXT_FLAGS));result.put("actual_context_profile",GL11.glGetInteger(GL32.GL_CONTEXT_PROFILE_MASK));result.put("context_origin",captured.has("gl_context_flags")?"captured":"legacy core+forward recovered by verified 19-program binary compatibility probe");result.put("actual_capture",(!captured.getAsJsonObject("cpu_inputs").has("synthetic_fixture")||!captured.getAsJsonObject("cpu_inputs").get("synthetic_fixture").getAsBoolean()));result.put("gpu",captured.get("gpu"));result.put("driver",captured.get("driver"));result.put("passed",false);result.put("scope","actual complete published capture; no FPS claim; no Dome contact dispatch in this capture");var cases=new ArrayList<Map<String,Object>>();
  try{
   Map<String,Object> expected;
   try(var replay=new R7ChainReplayGpu.Replay(input,"production")){replay.run();var a=R8SemanticState.snapshot(replay);replay.run();var b=R8SemanticState.snapshot(replay);result.put("production_AA_equal",a.equals(b));result.put("production_AA_difference_fields",differences(a,b));result.put("production_AA",List.of(digests(a),digests(b)));result.put("program_loading",replay.programLoading);}
   try(var replay=new R7ChainReplayGpu.Replay(input,"complete-reference")){replay.run();expected=R8SemanticState.snapshot(replay);replay.run();check(expected.equals(R8SemanticState.snapshot(replay)),"complete reference semantic AA");}result.put("reference_passed",true);result.put("reference_state",digests(expected));check(((Number)expected.get("models")).intValue()>0,"actual active MODEL workload required");
   int[] policies={1,2,4,16,7,4,4,8,12,15};
   for(int route=0;route<policies.length;route++){
    int policy=policies[route];String backend=route==5?"rt-triangle":route==6?"cuda-control":"rt-aabb";System.setProperty("cmi.r8.policy",Integer.toString(policy));var entry=new LinkedHashMap<String,Object>();entry.put("backend",backend);entry.put("policy",policy);entry.put("passed",false);
    try{
     if((policy&8)!=0){System.setProperty("cmi.r8.forceAudit","true");try(var replay=new R7ChainReplayGpu.Replay(input,backend)){replay.run();compare(expected,R8SemanticState.snapshot(replay),true);check(replay.hardware.fallbacks==0&&replay.hardware.forceQueries==replay.hardware.ordinaryQueries&&replay.hardware.forceQueries>0,"all actual ordinary force rows independently verified");entry.put("force_queries_verified",replay.hardware.forceQueries);}finally{System.clearProperty("cmi.r8.forceAudit");}}
     try(var replay=new R7ChainReplayGpu.Replay(input,backend)){replay.run();var actual=R8SemanticState.snapshot(replay);compare(expected,actual,(policy&8)!=0);check(replay.hardware.ordinaryQueries+replay.hardware.domeQueries>0&&replay.hardware.fallbacks==0,"actual nonempty native query consumed without fallback");entry.put("ordinary_queries",replay.hardware.ordinaryQueries);entry.put("dome_queries",replay.hardware.domeQueries);entry.put("ordinary_neighbors",replay.hardware.ordinaryNeighbors);entry.put("dome_neighbors",replay.hardware.domeNeighbors);entry.put("ordinary_native",replay.hardware.ordinaryUsed);entry.put("dome_native",replay.hardware.domeUsed);entry.put("fallbacks",replay.hardware.fallbacks);entry.put("state",digests(actual));entry.put("passed",true);}
    }catch(AssertionError|Exception failed){entry.put("failure",failed.toString());}finally{System.clearProperty("cmi.r8.forceAudit");}
    cases.add(entry);System.out.println("R8 actual "+backend+" policy="+policy+" passed="+entry.get("passed"));
   }
   var fingerprints=new TreeMap<String,String>();for(Path root:List.of(Path.of("build/classes/java/main"),Path.of("native/offload"),Path.of("src/main/resources/assets/createmanaindustry/shaders"))){try(var files=Files.walk(root)){for(Path file:files.filter(Files::isRegularFile).toList())fingerprints.put(file.toString().replace((char)92,'/'),HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file))));}}for(String file:List.of(".gradle/hardware-offload/build/CmiHardwareOffload.dll",".gradle/neighbor-rt/dependencies.json"))fingerprints.put(file,HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(Path.of(file)))));result.put("file_sha256",fingerprints);result.put("passed",cases.subList(0,7).stream().allMatch(x->Boolean.TRUE.equals(x.get("passed"))));result.put("all_candidates_passed",cases.stream().allMatch(x->Boolean.TRUE.equals(x.get("passed"))));
  }finally{System.clearProperty("cmi.r8.policy");System.clearProperty("cmi.r8.forceAudit");result.put("cases",cases);result.put("checks",checks);R8ForceOracle.close();Files.writeString(out.resolve("real-chain.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result));GLFW.glfwDestroyWindow(window);GLFW.glfwTerminate();}
 }
}
